insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('SN', 'SN-P-10', 'Hébergement touristique 10 %', '{}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2013-01-01', null, 'Code général des impôts, art. 369, alinéa 2 ; art. 383 b) — la taxe sur le logement, la restauration et les réceptions n''est déductible que dans les cas qu''il énumère, dont le logement du personnel de gardiennage sur chantier', 'S', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'loi-2015-06', null, null, null, null),
  ('SN', 'SN-P-18', 'Achats de biens 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2013-01-01', null, 'Code général des impôts, art. 374 — déduction de la taxe supportée sur les biens et services acquis pour les besoins de l''exploitation ; art. 376 — facture portant les mentions de l''art. 447 ; art. 369 pour le taux', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-P-18-IMMO', 'Immobilisations 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2013-01-01', null, 'Code général des impôts, art. 374 et 376 — déduction de la taxe ayant grevé les biens constituant des immobilisations ; art. 386 à 388 — régularisations', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-P-18-ND', 'Achat 18 % non déductible (art. 383)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2013-01-01', null, 'Code général des impôts, art. 383 — exclusions du droit à déduction, notamment c) les véhicules et engins conçus pour transporter des personnes ou à usage mixte, sauf revente à l''état neuf ou location professionnelle, a) les cadeaux de plus de 20 000 F hors taxes et g) les meubles meublants autres que le mobilier de bureau. La taxe est une part du coût de ce qui a été acheté', 'S', null, 150, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-P-18-PC', 'Achat 18 % soumis au précompte (art. 372)', '{}'::jsonb, 'Taxe retenue par un acquéreur précompteur', 'percent', 18, 'purchase', 'domestic', date '2013-01-01', null, 'Code général des impôts, art. 372-1 et 372-2 — l''acquéreur désigné par l''article (État, collectivités publiques, établissements publics, concessionnaires d''eau, d''électricité et de téléphone, entreprises de BTP relevant du service des grandes entreprises, producteurs et importateurs de ciment et distributeurs de produits pétroliers pour le transport) retient l''intégralité de la taxe facturée, la reverse sur une déclaration de précompte distincte de la déclaration de TVA et la déduit dès lors qu''elle a été déclarée (372-2 e) ; art. 372-3 pour les exceptions, dont les fournisseurs relevant de la DGE. Le fournisseur est payé hors taxe ; la taxe retenue attend son reversement au compte 4478', 'S', null, 160, 'vat', true, array['buyer_status']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-P-18-SRV', 'Services extérieurs 18 %', '{}'::jsonb, null, 'percent', 18, 'purchase', 'domestic', date '2013-01-01', null, 'Code général des impôts, art. 374 et 376 — déduction de la taxe supportée sur les services acquis pour les besoins de l''exploitation ; art. 369', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-P-IMP-18', 'Importation 18 % (TVA acquittée en douane)', '{}'::jsonb, null, 'percent', 18, 'purchase', 'import', date '2013-01-01', null, 'Code général des impôts, art. 362-4 et 363-2 — à l''importation, le fait générateur est la mise à la consommation et la taxe est exigible dès ce moment ; art. 376 — les documents douaniers justifient la déduction. La taxe est payée au service des douanes et déduite ici', null, null, 170, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-P-NR-18', 'Services de prestataires non établis 18 %, transfert de savoir-faire', '{}'::jsonb, null, 'percent', 18, 'purchase', 'foreign_services_received', date '2021-01-01', null, 'Code général des impôts, art. 355-3 — la taxe due par un assujetti non établi au Sénégal sans représentant fiscal est due par le destinataire (TVA pour compte) ; art. 383 f), dans la rédaction de la loi de finances pour 2021, et arrêté n° 039532 du 2 décembre 2021 — elle n''est déductible que pour les prestations qui emportent un transfert de savoir-faire', null, null, 180, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-P-NR-18-ND', 'Services de prestataires non établis 18 %, non déductible', '{}'::jsonb, null, 'percent', 18, 'purchase', 'foreign_services_received', date '2021-01-01', null, 'Code général des impôts, art. 355-3 — TVA pour compte due par le destinataire ; art. 383 f), dans la rédaction de la loi de finances pour 2021 — la taxe sur les services rendus par des prestataires non établis au Sénégal n''est pas déductible, sauf transfert de savoir-faire ; elle devient une part du coût du service', null, null, 190, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-S-10', 'Hébergement touristique agréé 10 %', '{}'::jsonb, 'Prestations des établissements d''hébergement touristique agréés', 'percent', 10, 'sale', 'domestic', date '2013-01-01', null, 'Code général des impôts, art. 369, alinéa 2, dans la rédaction de la loi n° 2015-06 du 23 mars 2015, art. 34 — « Ce taux est réduit à 10 % pour les prestations fournies par les établissements d''hébergement touristique agréés ». De 2013 à 2015, le taux réduit ne visait que leurs prestations d''hébergement et de restauration. Un restaurant qui n''est pas un établissement d''hébergement agréé facture 18 %.', 'S', null, 30, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'loi-2015-06', null, null, null, null),
  ('SN', 'SN-S-18', 'Ventes de biens 18 %', '{}'::jsonb, 'Livraisons de biens au taux normal, TVA au compte 4431', 'percent', 18, 'sale', 'domestic', date '2013-01-01', null, 'Code général des impôts, art. 369, alinéa 1 — taux de 18 %, taux unique de la taxe depuis l''entrée en vigueur du Code le 1er janvier 2013 ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux normal unique compris entre 15 % et 20 %', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-S-18-SRV', 'Prestations de services 18 %', '{}'::jsonb, 'Prestations de services au taux normal, TVA au compte 4432', 'percent', 18, 'sale', 'domestic', date '2013-01-01', null, 'Code général des impôts, art. 369, alinéa 1 — taux de 18 %, taux unique de la taxe depuis l''entrée en vigueur du Code le 1er janvier 2013 ; directive n° 02/2009/CM/UEMOA, art. 29 nouveau — taux normal unique compris entre 15 % et 20 % ; art. 362-3 — le fait générateur d''une prestation est son accomplissement, et le Code ne connaît ni régime général de l''encaissement ni option pour les débits : la taxe n''est donc pas portée ici en cash_basis', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-S-EXO', 'Opération exonérée (art. 361)', '{}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2013-01-01', null, 'Code général des impôts, art. 361 — opérations exonérées, dans la numérotation 1) à 28) de la loi n° 2018-10 ; sans droit à déduction sauf les cas de l''art. 380 ; art. 449-2 — état des exonérations joint à la déclaration ; art. 447-I-5 — la facture cite la disposition d''exonération', 'E', null, 50, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null),
  ('SN', 'SN-S-EXP', 'Exportation exonérée', '{}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2013-01-01', null, 'Code général des impôts, art. 361, 14) — exonération des exportations directes de biens et opérations assimilées ainsi que des services directement liés ; art. 380 a) — opération exonérée ouvrant droit à déduction ; art. 447-I-5 — la facture cite la disposition d''exonération', 'G', null, 40, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'cgi', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

