insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('SN', 'SN-TVA', 'Déclaration de taxe sur la valeur ajoutée', array['month', 'quarter']::declaration_period[], null, date '2013-01-01', null, 'Code général des impôts, art. 449-1 — déclaration mensuelle au régime du réel normal, due même sans opération ; art. 449-3 — déclaration trimestrielle au régime du réel simplifié ; art. 449-1 — pas de déclaration de TVA pour les contribuables à la contribution globale unique ; art. 449-4 — la déclaration porte le montant des opérations taxables et exonérées, la taxe exigible, les déductions et les régularisations, sur des imprimés dont le modèle est fixé par note du Directeur général des Impôts et des Domaines ; art. 449-5 — télédéclaration. La cadence dépend du régime de l''entreprise, donc de son chiffre d''affaires : le pack n''en propose aucune. Le modèle de l''imprimé n''est pas publié et la numérotation de ses cases n''est pas reprise ici ; SENTAX (sentax.dgid.sn) est obligatoire pour les entreprises de la DGE depuis le 1er septembre 2026.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Code général des impôts, art. 363-1 — la taxe est exigible le mois suivant celui du fait générateur, au plus tard le 15 ; art. 449-1 et 449-3 — la déclaration mensuelle et la déclaration trimestrielle du réel simplifié sont déposées au plus tard le 15 du mois qui suit la période. Le calendrier de la DGID reprend le 15.', 'cgi', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

insert into tax_report_box_templates
  (country, report_code, box, kind, name, name_i18n, sequence, print_sequence,
   plus_boxes, minus_boxes, rate, rate_of_box, floor_zero, hidden, xml_element,
   legal_reference, source_key)
values
  ('SN', 'SN-TVA', 'CA18', 'base', 'Opérations taxables au taux normal de 18 %', '{}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — la déclaration porte le montant des opérations taxables ; art. 369, alinéa 1 pour le taux. Le modèle officiel de l''imprimé est fixé par note du Directeur général des Impôts et des Domaines (art. 449-4) et n''est pas publié : les cases de ce formulaire suivent le contenu que l''article 449-4 impose, et non la numérotation de l''imprimé', 'cgi'),
  ('SN', 'SN-TVA', 'CA10', 'base', 'Opérations taxables au taux réduit de 10 %', '{}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 et art. 369, alinéa 2 — prestations des établissements d''hébergement touristique agréés', 'cgi'),
  ('SN', 'SN-TVA', 'EXP', 'base', 'Exportations et opérations assimilées exonérées ouvrant droit à déduction', '{}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — montant des opérations exonérées ; art. 361, 14) et art. 380 a) — exportations exonérées ouvrant droit à déduction', 'cgi'),
  ('SN', 'SN-TVA', 'EXO', 'base', 'Autres opérations exonérées', '{}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — montant des opérations exonérées, et art. 449-2 — état détaillé des exonérations joint à la déclaration ; art. 361 pour la liste', 'cgi'),
  ('SN', 'SN-TVA', 'CAT', 'total', 'Montant total des opérations réalisées', '{}'::jsonb, 50, null, array['CA18', 'CA10', 'EXP', 'EXO']::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — montant des opérations taxables et exonérées', 'cgi'),
  ('SN', 'SN-TVA', 'TVA18', 'tax', 'Taxe exigible au taux de 18 %', '{}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — taxe exigible ; art. 363-1 — exigible le mois suivant celui du fait générateur', 'cgi'),
  ('SN', 'SN-TVA', 'TVA10', 'tax', 'Taxe exigible au taux de 10 %', '{}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — taxe exigible ; art. 369, alinéa 2', 'cgi'),
  ('SN', 'SN-TVA', 'TVAPC', 'tax', 'TVA due pour le compte de prestataires non établis au Sénégal', '{}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 355-3 — à défaut de représentant fiscal, la taxe due par un assujetti non établi au Sénégal est due par le destinataire de l''opération. Le calendrier de la DGID fixe au 15 du mois suivant l''échéance de la « TVA pour compte » sur une ligne distincte de celle de la TVA : si l''administration la reçoit sur un imprimé séparé, cette case en est la transcription et non une case de la déclaration mensuelle', 'cgi'),
  ('SN', 'SN-TVA', 'TVAB', 'total', 'Total de la taxe exigible', '{}'::jsonb, 90, null, array['TVA18', 'TVA10', 'TVAPC']::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — taxe exigible', 'cgi'),
  ('SN', 'SN-TVA', 'DEDIMMO', 'tax', 'TVA déductible sur immobilisations', '{}'::jsonb, 100, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — déductions ; art. 374 et 376 — droit à déduction et justificatifs, l''annexe de l''art. 376-2 a) détaillant les déductions par fournisseur', 'cgi'),
  ('SN', 'SN-TVA', 'DEDBS', 'tax', 'TVA déductible sur biens et services', '{}'::jsonb, 110, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — déductions ; art. 374, 376 et 379 — déduction au titre du mois de réception de la facture ; art. 372-2 e) — la taxe précomptée et déclarée est déductible chez celui qui l''a retenue', 'cgi'),
  ('SN', 'SN-TVA', 'DEDT', 'total', 'Total des déductions', '{}'::jsonb, 120, null, array['DEDIMMO', 'DEDBS']::text[], '{}'::text[], null, null, false, false, null, 'Code général des impôts, art. 449-4 — déductions', 'cgi'),
  ('SN', 'SN-TVA', 'NET', 'total', 'TVA nette à payer', '{}'::jsonb, 130, null, array['TVAB']::text[], array['DEDT']::text[], null, null, true, false, null, 'Code général des impôts, art. 449-4 et 363-1 — la déclaration vaut titre de perception de la taxe exigible diminuée des déductions', 'cgi'),
  ('SN', 'SN-TVA', 'CRED', 'total', 'Crédit de TVA à reporter', '{}'::jsonb, 140, null, array['DEDT']::text[], array['TVAB']::text[], null, null, true, false, null, 'Code général des impôts, art. 375 et 379-2 — l''excédent de taxe déductible s''impute sur les mois suivants, sans pouvoir dépasser deux ans ; art. 390 à 393 pour la restitution', 'cgi')
on conflict (country, report_code, box, kind) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  sequence        = excluded.sequence,
  print_sequence  = excluded.print_sequence,
  plus_boxes      = excluded.plus_boxes,
  minus_boxes     = excluded.minus_boxes,
  rate            = excluded.rate,
  rate_of_box     = excluded.rate_of_box,
  floor_zero      = excluded.floor_zero,
  hidden          = excluded.hidden,
  xml_element     = excluded.xml_element,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

