values
  ('SN-SYSCOHADA-BS', 'SN', 'default', 'Bilan — Système normal', 'balance_sheet', 'SYSCOHADA', date '2018-01-01', null, 'Acte uniforme relatif au droit comptable et à l''information financière (AUDCIF) du 26 janvier 2017, art. 25, 26 et 29 ; Système comptable OHADA, Titre IX, chapitre 3 (modèle de bilan) et chapitre 7 (tableau de correspondance postes/comptes). En vigueur pour les comptes personnels des entités au 1er janvier 2018 (AUDCIF, art. 113).', 'syscohada'),
  ('SN-SYSCOHADA-IS', 'SN', 'default', 'Compte de résultat — Système normal', 'income_statement', 'SYSCOHADA', date '2018-01-01', null, 'Acte uniforme relatif au droit comptable et à l''information financière (AUDCIF) du 26 janvier 2017, art. 25, 26 et 29 ; Système comptable OHADA, Titre IX, chapitre 4 (modèle de compte de résultat) et chapitre 7 (tableau de correspondance postes/comptes). Les charges y sont lues en positif et retranchées par les soldes intermédiaires, là où le modèle les imprime affectées du signe « - ».', 'syscohada')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

